17	//   - 被业务拒绝但本应写入免修历史的首次申请，遇保存失败时不能显示“已记入
18	//     免修历史”，退出码 2（文件错误优先于业务拒绝码 1），历史中查不到该申请；
19	//   - 有效免修只有保存成功后才允许显示“有效”及获得学分的信息。
20	
21	// makeDirUnwritable 取消目录的写权限并在测试结束时恢复。以 root 运行时权限
22	// 位无法阻止写入，此时跳过相关用例。
23	func makeDirUnwritable(t *testing.T, dir string) {
24		t.Helper()
25		if os.Geteuid() == 0 {
26			t.Skip("root 账户不受目录写权限限制，无法模拟保存失败")
27		}
28		if err := os.Chmod(dir, 0o555); err != nil {
29			t.Fatalf("取消目录写权限失败：%v", err)
30		}
31		t.Cleanup(func() { _ = os.Chmod(dir, 0o755) })
32	}
33	
34	// assertSaveFailure 断言一次写入类命令在保存阶段失败：退出码 2、标准输出
35	// 没有任何业务内容，标准错误明确指出保存失败并点名目标记录文件。
36	func assertSaveFailure(t *testing.T, file string, args []string, forbidden []string, label string) {
37		t.Helper()
38		out, errText, code := runCLI(t, file, args...)
39		if code != exitFile {
40			t.Fatalf("%s：保存失败应退出码 %d，code=%d out=%q err=%q",
41				label, exitFile, code, out, errText)
42		}
43		if out != "" {
44			t.Fatalf("%s：保存未完成时标准输出不应包含业务结果，out=%q", label, out)
45		}
46		for _, want := range []string{"保存记录文件", file, "失败"} {
47			if !strings.Contains(errText, want) {
48				t.Fatalf("%s：错误输出应说明保存失败并点名目标记录文件（缺 %q），err=%q",
49					label, want, errText)
50			}
51		}
52		for _, bad := range forbidden {
53			if strings.Contains(errText, bad) || strings.Contains(out, bad) {
54				t.Fatalf("%s：保存失败时不得出现 %q，out=%q err=%q", label, bad, out, errText)
55			}
56		}
57	}
58	
59	// TestCLISaveFailureMissingParentHidesBusinessResult 目标记录文件与父目录都
60	// 不存在时登记学生：保存失败必须以退出码 2 结束，标准输出保持为空，不能先
61	// 显示“已登记学生”，也不能谎称已创建记录文件。
62	func TestCLISaveFailureMissingParentHidesBusinessResult(t *testing.T) {
63		file := filepath.Join(t.TempDir(), "missing-parent", "records.json")
64	
65		assertSaveFailure(t, file, []string{"student", "s1"},
66			[]string{"已登记学生", "已从空记录开始并创建", "从空记录"}, "首次登记学生")
67	
68		if _, err := os.Stat(file); !os.IsNotExist(err) {
69			t.Fatalf("保存失败后不得创建记录文件，stat err=%v", err)
70		}
71		if _, err := os.Stat(filepath.Dir(file)); !os.IsNotExist(err) {
72			t.Fatalf("保存失败后不得创建父目录，stat err=%v", err)
73		}
74	}
75	
76	// TestCLISaveFailureKeepsExistingFileUnchanged 修改已有记录时保存失败：退出码
77	// 2、标准输出为空，原文件逐字节保留，本次新增的学生不得落盘。
78	func TestCLISaveFailureKeepsExistingFileUnchanged(t *testing.T) {
79		dir := t.TempDir()
80		file := filepath.Join(dir, "records.json")
