224	func cmdReq(s *credit.Store, args []string, out io.Writer) (int, error) {
225		if len(args) != 3 {
226			return exitRejected, errors.New("用法：req <学生> <要求编号> <课程编号>")
227		}
228		r, action, err := s.AddRequirement(args[0], args[1], args[2])
229		if err != nil {
230			return exitRejected, err
231		}
232		if action == credit.ActionCreated {
233			fmt.Fprintf(out, "已为学生 %s 登记要求 %s，指向课程 %s\n", r.StudentID, r.ID, r.CourseID)
234		} else {
235			fmt.Fprintf(out, "学生 %s 的要求 %s 已存在且内容一致，返回原记录\n", r.StudentID, r.ID)
236		}
237		return exitOK, nil
238	}
