11	// 本文件从命令行入口回归“保存时不得悄悄改写文字”。命令行参数在本机上可以
12	// 携带非法 UTF-8 字节（Go 的字符串按字节保留，不做替换），这些字节会原样
13	// 进入待保存的编号、名称、学期、依据或原因。标准库序列化会把它们静默替换成
14	// U+FFFD 却提示成功，因此保存必须明确拒绝这种数据：
15	//   - 退出码沿用保存失败的 2，标准错误说明保存失败、点名目标文件，并指出
16	//     无法原样保存的文字所在的记录类别与具体字段；
17	//   - 标准输出不能出现登记成功、免修已生效、历史已保存或文件已创建等提示；
18	//   - 已有记录文件逐字节保留、原先能查询的学生与学分照常查询；目标文件原本
19	//     不存在时不得留下新记录文件或临时文件；
20	//   - 即使问题只在一条已拒绝免修的文字里，也拒绝整次保存，历史不落盘；
21	//   - 合法文字（用户确实输入的“�”、中文与补充平面字符、编号中合法的控制
22	//     字符、依据中的空白、字面上的“\uD800”）继续正常保存使用。
23	
24	// invalidUTF8Arg 返回一个带非法 UTF-8 字节的参数。
25	func invalidUTF8Arg(prefix string) string { return prefix + string([]byte{0xFF}) }
26	
27	// assertSaveRejectsBadText 在“保存失败”通用断言之外，额外要求错误指出无法
28	// 原样保存的文字、记录类别与具体字段。
29	func assertSaveRejectsBadText(t *testing.T, file string, args []string, category, field, label string) {
30		t.Helper()
31		out, errText, code := runCLI(t, file, args...)
32		if code != exitFile {
33			t.Fatalf("%s：应按保存失败退出码 %d 结束，code=%d out=%q err=%q",
34				label, exitFile, code, out, errText)
35		}
36		if out != "" {
37			t.Fatalf("%s：保存失败时标准输出必须为空，out=%q", label, out)
38		}
39		for _, want := range []string{"保存记录文件", file, "失败", "无法原样保存", category, field} {
40			if !strings.Contains(errText, want) {
41				t.Fatalf("%s：错误输出应包含 %q（说明保存失败、目标文件、类别 %q 与字段 %q），err=%q",
42					label, want, category, field, errText)
43			}
44		}
45	}
46	
47	// TestCLISaveRejectsInvalidUTF8NotCreated 目标文件原本不存在时，待保存文字
48	// 含非法 UTF-8（学生编号、课程名称、学期、免修依据等）必须拒绝整次保存：
49	// 退出码 2、标准输出为空，目标文件与临时文件都不得留下。
50	func TestCLISaveRejectsInvalidUTF8NotCreated(t *testing.T) {
51		cases := []struct {
52			label    string
53			args     []string
54			category string
55			field    string
56		}{
57			{"学生编号非法", []string{"student", invalidUTF8Arg("s")}, "学生", "编号"},
58			{"课程编号非法", []string{"course", invalidUTF8Arg("c"), "数学", "4"}, "课程", "编号"},
59			{"课程名称非法", []string{"course", "c1", invalidUTF8Arg("数学"), "4"}, "课程", "名称"},
60			{"学期非法", []string{"enroll", "s1", "r1", invalidUTF8Arg("2024春"), "e1"}, "修读", "学期"},
61			{"免修依据非法", []string{"waiver", "s1", "r1", "w9", invalidUTF8Arg("依据")}, "免修", "依据"},
62			{"撤销原因非法", []string{"revoke-waiver", "s1", "w1", invalidUTF8Arg("原因")}, "免修", "原因"},
63		}
64		for _, c := range cases {
65			t.Run(c.label, func(t *testing.T) {
66				dir := t.TempDir()
67				file := filepath.Join(dir, "records.json")
68				// enroll/waiver/revoke 需要前置记录；这些前置命令本身必须正常落盘。
69				for _, st := range [][]string{
70					{"student", "s1"},
71					{"course", "c1", "数学", "4"},
72					{"req", "s1", "r1", "c1"},
73					{"waiver", "s1", "r1", "w1", "原始依据"},
74				} {
75					if _, errText, code := runCLI(t, file, st...); code != 0 {
76						t.Fatalf("前置步骤 %v 失败，code=%d err=%q", st, code, errText)
77					}
78				}
79				before, err := os.ReadFile(file)
80				if err != nil {
81					t.Fatal(err)
82				}
83	
