95	// TestSaveRejectsInvalidUTF8PerField 待保存记录里任意字符串字段含非法
96	// UTF-8 时，Save 必须在写入前拒绝：错误说明存在无法原样保存的文字，并
97	// 指出记录类别与具体字段；目标文件（原本不存在）不得被创建；原始字符串
98	// 不能被修补、清空或替换。
99	func TestSaveRejectsInvalidUTF8PerField(t *testing.T) {
100		for _, tg := range saveFieldTargets() {
101			t.Run(tg.category+"-"+tg.field, func(t *testing.T) {
102				s := saveTextBaseStore(t)
103				tg.corrupt(s)
104	
105				path := filepath.Join(t.TempDir(), "records.json")
106				err := s.Save(path)
107				if err == nil {
108					t.Fatalf("%s的%s含非法 UTF-8 时应拒绝保存", tg.category, tg.field)
109				}
110				msg := err.Error()
111				for _, want := range []string{"无法原样保存", tg.category, tg.field, path} {
112					if !strings.Contains(msg, want) {
113						t.Fatalf("错误应说明无法原样保存并指出类别 %q 与字段 %q、点名目标文件，得到：%v",
114							tg.category, tg.field, err)
115					}
116				}
117				if _, statErr := os.Stat(path); !os.IsNotExist(statErr) {
118					t.Fatalf("拒绝保存后不得在原本不存在的位置留下记录文件，stat err=%v", statErr)
119				}
