121				leftover, _ := filepath.Glob(filepath.Join(filepath.Dir(path), ".credit-*.tmp"))
122				if len(leftover) != 0 {
123					t.Fatalf("拒绝保存后不得残留临时文件：%v", leftover)
124				}
125				// 原始字符串保持原样：非法字节仍在，绝不能被替换成 U+FFFD。
126				raw := tg.rawField(s)
127				if utf8.ValidString(raw) || !strings.ContainsRune(raw, 'x') ||
128					!strings.Contains(raw, badByte) {
129					t.Fatalf("拒绝保存不得修补原始字段，得到 % x", []byte(raw))
130				}
131				if strings.Contains(raw, "�") {
132					t.Fatalf("原始字段不得被替换成 U+FFFD，得到 % x", []byte(raw))
133				}
134			})
135		}
136	}
