353		t.Run("已撤销免修状态非法且该要求另有通过修读", func(t *testing.T) {
354			s := saveTextBaseStore(t)
355			// 先让 r1 拥有通过修读，再撤销 w1：撤销后的免修不提供学分，要求靠
356			// 通过修读照常满足——即使这样，问题免修自身的状态非法仍须拒绝整次保存。
357			if _, _, err := s.SubmitResult("s1", "e1", Passed); err != nil {
358				t.Fatal(err)
359			}
360			if _, _, err := s.RevokeWaiver("s1", "w1", "材料无法核实"); err != nil {
361				t.Fatal(err)
362			}
363			w := s.Waiver("s1", "w1")
364			if w.Status != WaiverRevoked {
365				t.Fatalf("测试前置：w1 应为已撤销免修，得到 %+v", w)
366			}
367			basisBefore := w.Basis
368			w.Status = WaiverStatus("revoked" + badByte)
369	
370			path := filepath.Join(t.TempDir(), "records.json")
371			err := s.Save(path)
372			if err == nil {
373				t.Fatal("已撤销免修自身的状态含非法字节时必须拒绝整次保存，即使该要求另有通过修读")
374			}
375			msg := err.Error()
376			for _, want := range []string{"无法原样保存", "免修", "w1", "状态", path} {
377				if !strings.Contains(msg, want) {
378					t.Fatalf("错误应点名目标文件、免修记录编号 w1 与字段“状态”，得到：%v", err)
379				}
380			}
381			if _, statErr := os.Stat(path); !os.IsNotExist(statErr) {
382				t.Fatalf("拒绝保存后不得创建记录文件，stat err=%v", statErr)
383			}
384			// 内存中原依据、撤销原因与通过修读都不被改动，历史不被删除。
385			mw := s.Waiver("s1", "w1")
386			if mw == nil || !strings.Contains(string(mw.Status), badByte) {
387				t.Fatalf("内存中的原始状态不得被修补：%+v", mw)
388			}
389			if mw.Basis != basisBefore || mw.Reason != "材料无法核实" {
390				t.Fatalf("原依据与撤销原因不得被改动：%+v", mw)
391			}
392			if e := s.Enrollment("s1", "e1"); e == nil || e.Result != Passed {
393				t.Fatalf("通过修读不得被改动：%+v", e)
394			}
395		})
396	}
397	
398	// TestSaveResultStatusLegalReplacementCharAccepted 修读“结果”与免修“状态”
399	// 这两个字段与编号、名称、学期、依据、原因遵守同一条 UTF-8 规则：用户确实输入
400	// 的“�”（U+FFFD）是合法字符，不能仅凭它出现在结果或状态文字中就判为非法
401	// 字节；只有真正的非法字节才拒绝。这里直接校验这两个字段的判定，避免与“结果/
402	// 状态只能取固定业务值”的既有读取规则（loadData 的枚举校验）混在一起——业务
403	// 允许的标准状态（通过/未通过、有效/已拒绝/已撤销）照常保存与读取由其余用例
404	// 覆盖。
405	func TestSaveResultStatusLegalReplacementCharAccepted(t *testing.T) {
406		for _, c := range []struct {
407			category, id, field, value string
408		}{
409			{"修读", "e1", "结果", "passed�-合法"},
410			{"修读", "e1", "结果", "未通过�"},
411			{"免修", "w1", "状态", "rejected�-状态"},
412			{"免修", "w1", "状态", "�"},
413		} {
414			if err := checkSaveText(c.category, c.id, c.field, c.value); err != nil {
415				t.Fatalf("%s记录 %s 的字段“%s”含合法 U+FFFD 时不应被判为非法文字：%v",
416					c.category, c.id, c.field, err)
417			}
418			// 同一文字中夹入真正的非法字节仍必须拒绝。
419			bad := c.value + badByte
420			err := checkSaveText(c.category, c.id, c.field, bad)
421			if err == nil {
422				t.Fatalf("%s记录 %s 的字段“%s”加入非法字节后必须拒绝", c.category, c.id, c.field)
423			}
424			var ite *invalidTextError
425			if !errors.As(err, &ite) || ite.category != c.category || ite.field != c.field || ite.id != c.id {
426				t.Fatalf("错误应点名类别 %q、编号 %q 与字段 %q，得到：%v",
427					c.category, c.id, c.field, err)
428			}
429		}
430	}
431	
432	// TestSaveDoesNotCollapseDistinctInvalidIDs 两个含有不同非法字节、本不相同
433	// 的编号，标准库替换后都会变成同一个“x�”：保存必须在替换发生前拒绝，绝不
434	// 能把它们写成两个同号学生、制造编号重复的损坏文件。
435	func TestSaveDoesNotCollapseDistinctInvalidIDs(t *testing.T) {
436		s := NewStore()
437		if _, _, err := s.AddStudent("s" + string([]byte{0xFE})); err != nil {
438			t.Fatal(err)
439		}
440		if _, _, err := s.AddStudent("s" + string([]byte{0x80})); err != nil {
441			t.Fatal(err)
442		}
443		path := filepath.Join(t.TempDir(), "records.json")
444		if err := s.Save(path); err == nil {
445			t.Fatal("含不同非法字节的编号必须拒绝保存，不能写成重复编号")
446		}
447		if _, err := os.Stat(path); !os.IsNotExist(err) {
448			t.Fatal("拒绝后不得创建文件")
449		}
450	}
451	
452	// TestSaveAcceptsLegalUnicodeText 合法文字继续按原文保存并可原样读回：
453	// 用户确实输入的“�”、中文与补充平面字符、编号中合法的控制字符、免修依据
454	// 中原有（含前后）的空白、命令行字面上的“\uD800”（反斜线加普通字母数字，
455	// 不是 Unicode 转义）都不能被误拒绝。
456	func TestSaveAcceptsLegalUnicodeText(t *testing.T) {
457		dir := t.TempDir()
458		path := filepath.Join(dir, "records.json")
459	
460		s := NewStore()
461		// 编号中合法的控制字符（U+0001）与用户确实输入的“�”。
462		mustStudent(t, s, "s\u0001")
463		mustStudent(t, s, "s�2")
464		// 中文与补充平面字符课程名称。
465		mustCourse(t, s, "c1", "高等数学😀", 4)
466		mustReq(t, s, "s\u0001", "r1", "c1")
467		// 学期含补充平面字符、修读编号含“�”。
468		mustEnroll(t, s, "s\u0001", "r1", "2024😀春", "e�1")
469		if _, _, err := s.SubmitResult("s\u0001", "e�1", Passed); err != nil {
470			t.Fatal(err)
471		}
472		// 依据前后与中间的空白必须原样保留；命令行里字面出现的“\uD800”只是
473		// 反斜线加普通字母数字（合法 ASCII 文字），不是记录文件里的 Unicode 转义。
474		literalBackslashU := `\uD800`
475		basis := "  竞赛\n获奖\t" + literalBackslashU + "  "
476		if w, _, err := s.ApplyWaiver("s\u0001", "r1", "w1", basis); err != nil ||
477			w.Status != WaiverApproved {
478			t.Fatalf("含空白与字面 \\uD800 的依据应正常生效：%+v %v", w, err)
479		}
480	
481		if err := s.Save(path); err != nil {
482			t.Fatalf("合法文字应正常保存：%v", err)
483		}
484	
485		loaded, _, err := Load(path)
486		if err != nil {
487			t.Fatalf("合法文字保存后应可正常读取：%v", err)
488		}
489		if loaded.Student("s\u0001") == nil {
490			t.Fatal("编号中合法的控制字符应原样保存")
491		}
492		if loaded.Student("s�2") == nil {
493			t.Fatal("用户确实输入的“�”是合法文字，应原样保存")
494		}
495		if c := loaded.Course("c1"); c == nil || c.Name != "高等数学😀" {
496			t.Fatalf("中文与补充平面字符应原样保存，得到 %+v", c)
497		}
498		if e := loaded.Enrollment("s\u0001", "e�1"); e == nil || e.Term != "2024😀春" {
499			t.Fatalf("含补充平面字符的学期与含“�”的修读编号应原样保存，得到 %+v", e)
500		}
501		w := loaded.Waiver("s\u0001", "w1")
502		if w == nil || w.Basis != basis || !strings.Contains(w.Basis, literalBackslashU) {
503			t.Fatalf("依据中的原有空白与字面 \\uD800 应原样保留，得到 %+v", w)
504		}
505		// 学分来源与核对结果不改变。
506		if rep := loaded.CheckStudent("s\u0001"); rep.TotalCredits != 4 || len(rep.Unmet) != 0 {
507			t.Fatalf("正常保存后核对结果不应改变，得到 %+v", rep)
508		}
509	}
