182	// loadLegalRecord 加载合法记录：必须成功、记录标记为已存在，且只读核对
183	// 不把记录标记为变更、不改写原文件；返回加载后的记录集。
184	func loadLegalRecord(t *testing.T, d *fileData) *Store {
185		t.Helper()
186		path, raw := writeRecord(t, d)
187		s, existed, err := Load(path)
188		if err != nil || !existed {
189			t.Fatalf("合法记录应正常读取，existed=%v err=%v", existed, err)
190		}
191		_ = s.CheckStudent("s1") // 只读核对本身不得改动记录。
192		if s.Dirty() {
193			t.Fatal("只读核对不应把记录标记为已变更")
194		}
195		got, readErr := os.ReadFile(path)
196		if readErr != nil {
197			t.Fatal(readErr)
198		}
199		if string(got) != string(raw) {
200			t.Fatalf("读取与核对不得改动合法记录文件\nwant=%q\n got=%q", raw, got)
201		}
202		return s
203	}
