205	// TestLoadReorderedPassesPickEarliestSeqSource 一项 4 学分要求有两次通过
206	// 修读，文件把后提交的记录排在前面，且修读编号与学期的先后都与提交先后
207	// 相反：没有有效免修时仍以提交序号较小的通过修读说明来源，两次通过都保留，
208	// 要求满足、总学分仍是 4。
209	func TestLoadReorderedPassesPickEarliestSeqSource(t *testing.T) {
210		// 文件顺序 [e1(seq2, 2024春), e2(seq1, 2024秋)]：
211		// 按文件排列、编号升序、学期升序都会挑到 e1，只有提交序号指向 e2。
212		d := seqBaseRecord()
213		d.Enrollments = []*Enrollment{
214			seqEnr("e1", "s1", "r1", "2024春", Passed, 2),
215			seqEnr("e2", "s1", "r1", "2024秋", Passed, 1),
216		}
217		d.NextResultSeq = 2
218		path, _ := writeRecord(t, d)
219		s, existed, err := Load(path)
220		if err != nil || !existed {
221			t.Fatalf("序号各不相同的合法记录应正常读取，existed=%v err=%v", existed, err)
222		}
223		rep := s.CheckStudent("s1")
224		if rep.TotalCredits != 4 || len(rep.Unmet) != 0 {
225			t.Fatalf("要求应满足且总学分仍是 4，得到学分=%d 未满足=%v",
226				rep.TotalCredits, rep.Unmet)
227		}
228		st := rep.Requirements[0]
229		if !st.Satisfied || st.Source != "enrollment" || st.PassedEnrollmentID != "e2" {
230			t.Fatalf("应以提交序号较小的通过修读 e2 说明来源，不能按文件排列/编号/学期挑选，得到 %+v", st)
231		}
232		if len(st.PassedEnrollmentIDs) != 2 ||
233			st.PassedEnrollmentIDs[0] != "e2" || st.PassedEnrollmentIDs[1] != "e1" {
234			t.Fatalf("两次通过记录都应按提交先后保留，得到 %v", st.PassedEnrollmentIDs)
235		}
236		if s.Dirty() {
237			t.Fatal("只读核对不应把记录标记为已变更")
238		}
239	
240		// 两条记录各自的结果、学期与序号保持原样。
241		e1 := s.Enrollment("s1", "e1")
242		e2 := s.Enrollment("s1", "e2")
243		if e1 == nil || e1.Result != Passed || e1.ResultSeq != 2 || e1.Term != "2024春" {
244			t.Fatalf("e1 应原样保留，得到 %+v", e1)
245		}
246		if e2 == nil || e2.Result != Passed || e2.ResultSeq != 1 || e2.Term != "2024秋" {
247			t.Fatalf("e2 应原样保留，得到 %+v", e2)
248		}
249	
250		// 用现有格式重新保存再加载：来源仍是序号最小的 e2，结论不漂移。
251		path2 := filepath.Join(t.TempDir(), "records.json")
252		if err := s.Save(path2); err != nil {
253			t.Fatalf("Save: %v", err)
254		}
255		reloaded, existed, err := Load(path2)
256		if err != nil || !existed {
257			t.Fatalf("重新保存后应可再次加载，existed=%v err=%v", existed, err)
258		}
259		rep2 := reloaded.CheckStudent("s1")
260		if rep2.TotalCredits != 4 || rep2.Requirements[0].PassedEnrollmentID != "e2" ||
261			len(rep2.Requirements[0].PassedEnrollmentIDs) != 2 {
262			t.Fatalf("重新加载后来源仍应是 e2、两次通过都保留，得到 %+v", rep2)
263		}
264	}
