590	
591	// Save 将全部记录原子写入 path：先写同目录临时文件，再重命名覆盖，
592	// 避免写到一半时损坏原文件。
593	//
594	// 写入前先做两项检查，任一失败都在创建临时文件之前返回错误，绝不替换、
595	// 清空或修补待保存记录，也不删除其中任何一条记录（不删修读、不调整序号、
596	// 不清除成绩或免修历史）；已有目标文件保持原样，目标原本不存在时不创建
597	// 记录文件、也不遗留临时文件：
598	//   - 全部待保存字符串必须是合法 UTF-8：标准库序列化会把非法字节静默替换
599	//     成 U+FFFD，含非法文字的数据绝不能进入序列化与临时文件阶段；
600	//   - 已提交成绩的正整数结果提交序号必须两两不同：序号表示整份记录中每次
601	//     首次提交成绩的先后，通过与未通过都占用一次；同一学生的重复修读与
602	//     不同学生的独立修读之间、不同要求或学期之间都不能共用同一序号。尚未
603	//     提交结果的修读沿用序号 0，多份并存不算重复；序号允许空缺。Load 会
604	//     把共用正整数序号的记录判为整份损坏，因此这里必须先拒绝，避免一次
605	//     “成功”的保存把可用文件换成随后读不回来的损坏文件。
606	func (s *Store) Save(path string) (err error) {
607		if err := s.validateSaveText(); err != nil {
608			return fmt.Errorf("记录中存在无法原样保存的文字，拒绝写入 %s：%w", path, err)
